public static char readChar(String validChars) 
{ 
Scanner sc = new Scanner(System.in); 
String line = sc.nextLine(); 
while(line.length() != 1 || !validChars.contains(line)) 
{ 
line = sc.nextLine(); 
} 
return line.charAt(0); 
} 
